/**
 * In-memory sample storage, one sorted bucket per series.
 *
 * Deliberately not durable: this is a bounded in-memory buffer over a recent
 * window — nothing is forwarded anywhere, and nothing reads it back.
 */

import type { Sample } from "./validate.ts";

export class MemoryStore {
  private readonly buckets = new Map<string, Sample[]>();
  private readonly maxPerSeries: number;

  constructor(maxPerSeries: number) {
    if (!Number.isInteger(maxPerSeries) || maxPerSeries <= 0) {
      throw new RangeError("maxPerSeries must be a positive integer");
    }
    this.maxPerSeries = maxPerSeries;
  }

  /** Insert a sample, keeping the series bucket ordered by timestamp. */
  put(sample: Sample): void {
    let bucket = this.buckets.get(sample.series);
    if (bucket === undefined) {
      bucket = [];
      this.buckets.set(sample.series, bucket);
    }
    const at = insertionPoint(bucket, sample.at);
    bucket.splice(at, 0, sample);
    if (bucket.length > this.maxPerSeries) {
      bucket.splice(0, bucket.length - this.maxPerSeries);
    }
  }

  /** Samples for `series` with `from <= at < to`, in timestamp order. */
  range(series: string, from: number, to: number): Sample[] {
    const bucket = this.buckets.get(series);
    if (bucket === undefined) return [];
    return bucket.filter((s) => s.at >= from && s.at < to);
  }

  /** Every series name currently holding at least one sample. */
  series(): string[] {
    return [...this.buckets.keys()].sort();
  }

  /** Drop every sample older than `before`; returns how many were removed. */
  prune(before: number): number {
    let removed = 0;
    for (const [name, bucket] of this.buckets) {
      const keep = bucket.filter((s) => s.at >= before);
      removed += bucket.length - keep.length;
      if (keep.length === 0) {
        this.buckets.delete(name);
      } else {
        this.buckets.set(name, keep);
      }
    }
    return removed;
  }

  size(): number {
    let total = 0;
    for (const bucket of this.buckets.values()) total += bucket.length;
    return total;
  }
}

/** Binary search for the index at which `at` keeps `bucket` sorted. */
function insertionPoint(bucket: Sample[], at: number): number {
  let low = 0;
  let high = bucket.length;
  while (low < high) {
    const mid = (low + high) >>> 1;
    if (bucket[mid].at <= at) low = mid + 1;
    else high = mid;
  }
  return low;
}

/**
 * Wiring. Everything above is injectable; this is the one place that decides
 * which real implementations get used.
 */

import type { Clock } from "./clock.ts";
import { SystemClock } from "./clock.ts";
import type { Config } from "./config.ts";
import { loadConfig } from "./config.ts";
import { IngestQueue } from "./ingest.ts";
import { MemoryStore } from "./store.ts";
import type { Router } from "./router.ts";
import { createRouter } from "./router.ts";

export interface Service {
  config: Config;
  store: MemoryStore;
  queue: IngestQueue;
  router: Router;
  /** Move queued samples into the store and expire anything past retention. */
  tick(): void;
}

export function createService(
  config: Config = loadConfig(),
  clock: Clock = new SystemClock(),
): Service {
  const store = new MemoryStore(config.maxSamples);
  const queue = new IngestQueue(config.maxSamples);
  const router = createRouter(store, config, clock);

  return {
    config,
    store,
    queue,
    router,
    tick(): void {
      for (const sample of queue.drain()) store.put(sample);
      store.prune(clock.now() - config.retentionMs);
    },
  };
}

export function main(): void {
  const service = createService();
  const series = service.store.series();
  process.stdout.write(
    `rollup service ready — window ${service.config.windowMs}ms, ${series.length} series\n`,
  );
}

if (process.argv[1] && process.argv[1].endsWith("index.ts")) {
  main();
}

/**
 * A tiny method+path router over the store. Transport-agnostic on purpose —
 * `dispatch` takes strings and returns a plain object, so it is testable
 * without binding a socket.
 */

import type { Clock } from "./clock.ts";
import type { Config } from "./config.ts";
import { parseSample } from "./ingest.ts";
import { rollup } from "./rollup.ts";
import { MemoryStore } from "./store.ts";
import { formatSummary, summarize } from "./summary.ts";
import { ValidationError } from "./validate.ts";

export interface Reply {
  status: number;
  body: string;
}

export class Router {
  private readonly store: MemoryStore;
  private readonly config: Config;
  private readonly clock: Clock;

  constructor(store: MemoryStore, config: Config, clock: Clock) {
    this.store = store;
    this.config = config;
    this.clock = clock;
  }

  dispatch(method: string, path: string, body = ""): Reply {
    if (method === "POST" && path === "/samples") {
      return this.ingest(body);
    }
    if (method === "GET" && path === "/series") {
      return { status: 200, body: this.store.series().join("\n") };
    }
    if (method === "GET" && path.startsWith("/summary/")) {
      return this.summary(path.slice("/summary/".length));
