/**
 * A tiny method+path router over the store. Transport-agnostic on purpose —
 * `dispatch` takes strings and returns a plain object, so it is testable
 * without binding a socket.
 */

import type { Clock } from "./clock.ts";
import type { Config } from "./config.ts";
import { parseSample } from "./ingest.ts";
import { rollup } from "./rollup.ts";
import { MemoryStore, SeriesLimitError } from "./store.ts";
import { formatSummary, summarize } from "./summary.ts";
import { ValidationError } from "./validate.ts";

export interface Reply {
  status: number;
  body: string;
}

export class Router {
  private readonly store: MemoryStore;
  private readonly config: Config;
  private readonly clock: Clock;

  constructor(store: MemoryStore, config: Config, clock: Clock) {
    this.store = store;
    this.config = config;
    this.clock = clock;
  }

  dispatch(method: string, path: string, body = ""): Reply {
    if (method === "POST" && path === "/samples") {
      return this.ingest(body);
    }
    if (method === "GET" && path === "/series") {
      return { status: 200, body: this.store.series().join("\n") };
    }
    if (method === "GET" && path.startsWith("/summary/")) {
      return this.summary(path.slice("/summary/".length));
    }
    return { status: 404, body: `no route for ${method} ${path}` };
  }

  private ingest(body: string): Reply {
    const lines = body.split("\n").filter((line) => line.trim() !== "");
    let accepted = 0;
    try {
      for (const line of lines) {
        this.store.put(parseSample(line, this.clock.now()));
        accepted += 1;
      }
    } catch (error) {
      if (error instanceof ValidationError) {
        return { status: 400, body: `${error.message} (accepted ${accepted})` };
      }
      throw error;
    }
    return { status: 202, body: `accepted ${accepted}` };
  }

  private summary(series: string): Reply {
    const windows = rollup(
      this.store,
      series,
      this.config.windowMs,
      this.clock.now(),
      this.config.retentionMs,
    );
    return { status: 200, body: formatSummary(summarize(windows, series)) };
  }
}

export function createRouter(
  store: MemoryStore,
  config: Config,
  clock: Clock,
): Router {
  return new Router(store, config, clock);
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { FixedClock } from "../src/clock.ts";
import { DEFAULT_CONFIG } from "../src/config.ts";
import { rollup, windowStart, windowsFor } from "../src/rollup.ts";
import { MemoryStore } from "../src/store.ts";
import { formatSummary, summarize } from "../src/summary.ts";

describe("windowStart", () => {
  it("aligns down to a multiple of the width", () => {
    assert.equal(windowStart(1_234, 1_000), 1_000);
    assert.equal(windowStart(1_000, 1_000), 1_000);
  });
});

describe("windowsFor", () => {
  it("buckets samples and carries min/max", () => {
    const windows = windowsFor(
      [
        { series: "a", value: 1, at: 0 },
        { series: "a", value: 3, at: 500 },
        { series: "a", value: 9, at: 1_500 },
      ],
      1_000,
    );
    assert.equal(windows.length, 2);
    assert.deepEqual(
      windows.map((w) => [w.from, w.count, w.min, w.max]),
      [
        [0, 2, 1, 3],
        [1_000, 1, 9, 9],
      ],
    );
  });

  it("omits empty windows rather than emitting zeroes", () => {
    const windows = windowsFor(
      [
        { series: "a", value: 1, at: 0 },
        { series: "a", value: 1, at: 5_000 },
      ],
      1_000,
    );
    assert.deepEqual(
      windows.map((w) => w.from),
      [0, 5_000],
    );
  });

  it("refuses a zero-width window", () => {
    assert.throws(() => windowsFor([], 0), RangeError);
  });
});

describe("rollup", () => {
  it("covers the trailing span only", () => {
    const store = new MemoryStore(100);
    store.put({ series: "a", value: 1, at: 1_000 });
    store.put({ series: "a", value: 5, at: 9_000 });

    const clock = new FixedClock(10_000);
    const windows = rollup(store, "a", 1_000, clock.now(), 2_000);

    assert.deepEqual(
      windows.map((w) => w.from),
      [9_000],
    );
  });
});

describe("summarize", () => {
  it("reports the empty case without inventing a measurement", () => {
    const summary = summarize([], "a");
    assert.equal(summary.count, 0);
    assert.equal(summary.from, null);
    assert.equal(formatSummary(summary), "a: no samples");
  });

  it("means across windows, not across window means", () => {
    const windows = windowsFor(
      [
        { series: "a", value: 1, at: 0 },
        { series: "a", value: 2, at: 1 },
        { series: "a", value: 9, at: 1_000 },
      ],
      1_000,
    );
    const summary = summarize(windows, "a");
    assert.equal(summary.count, 3);
    assert.equal(summary.mean, 4);
  });
});

describe("DEFAULT_CONFIG", () => {
  it("keeps a day of retention", () => {
    assert.equal(DEFAULT_CONFIG.retentionMs, 86_400_000);
  });
});

