import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { MemoryStore, SeriesLimitError } from "../src/store.ts";

describe("MemoryStore series cap", () => {
  it("rejects a new series once the store already holds maxSeries distinct series", () => {
    const store = new MemoryStore(10, 2);
    store.put({ series: "a", value: 1, at: 1 });
    store.put({ series: "b", value: 1, at: 1 });

    assert.throws(
      () => store.put({ series: "c", value: 1, at: 1 }),
      SeriesLimitError,
    );
    assert.deepEqual(store.series(), ["a", "b"]);
  });

  it("names the rejected series and the configured limit", () => {
    const store = new MemoryStore(10, 1);
    store.put({ series: "a", value: 1, at: 1 });

    try {
      store.put({ series: "b", value: 1, at: 1 });
      assert.fail("expected a SeriesLimitError");
    } catch (error) {
      assert.ok(error instanceof SeriesLimitError);
      assert.equal(error.series, "b");
      assert.equal(error.limit, 1);
    }
  });

  it("keeps admitting an existing series at the cap", () => {
    const store = new MemoryStore(10, 1);
    store.put({ series: "a", value: 1, at: 1 });
    store.put({ series: "a", value: 2, at: 2 });

    assert.deepEqual(
      store.range("a", 0, 10).map((s) => s.value),
      [1, 2],
    );
  });

  it("refuses a non-positive series cap", () => {
    assert.throws(() => new MemoryStore(10, 0), RangeError);
  });
});

