/**
 * A durable, on-disk record of admitted samples, replayed on startup so a
 * process restart resumes rather than starts empty.
 *
 * Deliberately not fsync'd: the write syscall's buffer already survives the
 * *process* exiting, which is the failure mode this covers — surviving the
 * host losing power mid-write is out of scope (see the ADR superseding
 * "keep the sample store in memory").
 */

import {
  existsSync,
  mkdirSync,
  readFileSync,
  renameSync,
  writeFileSync,
  appendFileSync,
} from "node:fs";
import { dirname } from "node:path";

import type { Sample } from "./validate.ts";
import { validateSample } from "./validate.ts";

export class Journal {
  private readonly path: string;

  constructor(path: string) {
    this.path = path;
    mkdirSync(dirname(path), { recursive: true });
  }

  /** Append one admitted sample. */
  append(sample: Sample): void {
    appendFileSync(this.path, `${JSON.stringify(sample)}\n`);
  }

  /** Rewrite the journal to hold exactly `samples`, discarding everything else. */
  compact(samples: Sample[]): void {
    const tmpPath = `${this.path}.tmp`;
    writeFileSync(tmpPath, samples.map((s) => `${JSON.stringify(s)}\n`).join(""));
    renameSync(tmpPath, this.path);
  }

  /**
   * Read back every well-formed entry, in append order.
   *
   * A line that fails to parse or validate — the shape a crash mid-append
   * leaves behind — is skipped rather than raising.
   */
  replay(): Sample[] {
    if (!existsSync(this.path)) return [];
    const lines = readFileSync(this.path, "utf8").split("\n");
    const samples: Sample[] = [];
    for (const line of lines) {
      if (line.trim() === "") continue;
      try {
        samples.push(validateSample(JSON.parse(line)));
      } catch {
        continue;
      }
    }
    return samples;
  }
}

