import type { Clock } from "./clock.ts";
import { SystemClock } from "./clock.ts";
import type { Config } from "./config.ts";
import { loadConfig } from "./config.ts";
import { IngestQueue } from "./ingest.ts";
import { Journal } from "./journal.ts";
import { MemoryStore, SeriesLimitError } from "./store.ts";
import type { Router } from "./router.ts";
import { createRouter } from "./router.ts";

export interface Service {
  config: Config;
  store: MemoryStore;
  queue: IngestQueue;
  journal: Journal;
  router: Router;
  /** Move queued samples into the store, journal them, and expire anything past retention. */
  tick(): void;
}

/** Restore a store's pre-restart contents from its durable journal. */
function replay(journal: Journal, store: MemoryStore, retainAfter: number): void {
  for (const sample of journal.replay()) {
    if (sample.at < retainAfter) continue;
    try {
      store.put(sample);
    } catch (error) {
      if (!(error instanceof SeriesLimitError)) throw error;
    }
  }
}

export function createService(
  config: Config = loadConfig(),
  clock: Clock = new SystemClock(),
): Service {
  const store = new MemoryStore(config.maxSamples, config.maxSeries);
  const queue = new IngestQueue(config.maxSamples);
  const journal = new Journal(config.journalPath);
  replay(journal, store, clock.now() - config.retentionMs);
  const router = createRouter(store, config, clock, journal);

