import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, it } from "node:test";

import { FixedClock } from "../src/clock.ts";
import { DEFAULT_CONFIG } from "../src/config.ts";
import { Journal } from "../src/journal.ts";
import { createRouter } from "../src/router.ts";
import { MemoryStore } from "../src/store.ts";

function tempJournal(): Journal {
  const dir = mkdtempSync(join(tmpdir(), "rosewater-router-"));
  return new Journal(join(dir, "journal.jsonl"));
}

describe("Router series-limit rejection", () => {
  it("replies 429 naming the limit, counts what already landed, and keeps the store usable", () => {
    const store = new MemoryStore(10, 1);
    const router = createRouter(store, DEFAULT_CONFIG, new FixedClock(1_000), tempJournal());

    const reply = router.dispatch("POST", "/samples", "a 1\nb 1");

    assert.equal(reply.status, 429);
    assert.match(reply.body, /series limit reached \(max 1\)/);
    assert.match(reply.body, /"b"/);
    assert.match(reply.body, /accepted 1/);
    assert.deepEqual(store.series(), ["a"]);

    const followUp = router.dispatch("POST", "/samples", "a 2");
    assert.equal(followUp.status, 202);
  });
});

describe("Router journaling", () => {
  it("persists an accepted sample to the journal, and not a rejected one", () => {
    const store = new MemoryStore(10, 10);
    const dir = mkdtempSync(join(tmpdir(), "rosewater-router-"));
    const journal = new Journal(join(dir, "journal.jsonl"));
    const router = createRouter(store, DEFAULT_CONFIG, new FixedClock(1_000), journal);

    router.dispatch("POST", "/samples", "a 1");
    router.dispatch("POST", "/samples", "bad-value-line-too-many-fields 1 2 3");

    assert.deepEqual(journal.replay(), [{ series: "a", value: 1, at: 1_000 }]);
    rmSync(dir, { recursive: true, force: true });
  });
});

