import assert from "node:assert/strict";
import { appendFileSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, it } from "node:test";

import { Journal } from "../src/journal.ts";

let dir: string;
let path: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "rosewater-journal-"));
  path = join(dir, "journal.jsonl");
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe("Journal", () => {
  it("replays exactly what was appended, in order", () => {
    const journal = new Journal(path);
    journal.append({ series: "a", value: 1, at: 1 });
    journal.append({ series: "a", value: 2, at: 2 });

    assert.deepEqual(journal.replay(), [
      { series: "a", value: 1, at: 1 },
      { series: "a", value: 2, at: 2 },
    ]);
  });

  it("starts empty when no journal file exists yet", () => {
    const journal = new Journal(path);
    assert.deepEqual(journal.replay(), []);
  });

  it("skips a truncated trailing entry left by a crash mid-append", () => {
    const journal = new Journal(path);
    journal.append({ series: "a", value: 1, at: 1 });
    appendFileSync(path, '{"series":"a","value":2,"at"');

    assert.deepEqual(journal.replay(), [{ series: "a", value: 1, at: 1 }]);
  });

  it("compacts to hold exactly the given samples, dropping everything else", () => {
    const journal = new Journal(path);
    journal.append({ series: "a", value: 1, at: 1 });
    journal.append({ series: "b", value: 2, at: 2 });
    journal.append({ series: "a", value: 3, at: 3 });

    journal.compact([{ series: "a", value: 3, at: 3 }]);

    assert.deepEqual(journal.replay(), [{ series: "a", value: 3, at: 3 }]);
    assert.equal(readFileSync(path, "utf8").trim().split("\n").length, 1);
  });
});

